import type { GuiSpriteName } from "@tennantite/textures";
import type { ReactNode } from "react";

import type { ScreenSlot } from "./screen-types";
import { GuiSprite } from "@/components/tennantite/gui-sprite";
import { ItemStack } from "@/components/tennantite/item-stack";
import { Slot } from "@/components/tennantite/slot";
import { cn, gui } from "@/components/tennantite/lib/tennantite-utils";

export interface ScreenItemSlotProps {
  className?: string;
  /**
  * 绘制槽位凹槽（默认 false；容器背景已烘焙槽框）
  */
  frame?: boolean;
  /**
  * 自定义槽框纹理类（默认原版 `mc-tex-slot`）
  */
  frameClassName?: string;
  /**
  * 空槽 ghost 精灵（盔甲/盾/箭等）
  */
  ghost?: GuiSpriteName;
  /**
  * 自定义 ghost 纹理类（与 `ghost` 二选一）
  */
  ghostClassName?: string;
  /**
  * 物品
  */
  item?: ScreenSlot;
  /**
  * 可访问名称（测试与读屏用，如 `armor-0`）
  */
  label: string;
  /**
  * 槽位左上角 x（GUI px，从面板外沿起算）
  */
  left: number;
  /**
  * 交互回调；省略时槽位不可点击
  */
  onActivate?: () => void;
  /**
  * 边长（GUI px，默认 18 —— 原版槽位；结果槽 26）
  */
  size?: number;
  /**
  * 槽位左上角 y（GUI px，从面板外沿起算）
  */
  top: number;
}

/**
 * 容器界面绝对定位槽位（规格 §6）：坐标即原版 `container/*.png` 的槽位左上角。
 * 物品图标固定 16 GUI px，在结果槽（26）内居中偏移 5。
 * 背景已含槽框，因此默认不重复绘制 `Slot` 凹槽。
 */
export function ScreenItemSlot({
  className,
  frame = false,
  frameClassName,
  ghost,
  ghostClassName,
  item,
  label,
  left,
  onActivate,
  size = 18,
  top,
}: ScreenItemSlotProps) {
  let content: ReactNode = null;
  if (item) {
    content = <ItemStack bare {...item} size={size} />;
  }
  else if (ghostClassName) {
    content = (
      <span
        aria-hidden="true"
        className={cn("block shrink-0", ghostClassName)}
        style={{ height: gui(16), width: gui(16) }}
      />
    );
  }
  else if (ghost) {
    content = <GuiSprite height={16} name={ghost} width={16} />;
  }

  return (
    <Slot
      aria-label={label}
      bare={!frame}
      className={cn("absolute", onActivate ? "cursor-pointer" : undefined, className)}
      frameClassName={frameClassName}
      onClick={onActivate}
      size={size}
      style={{ left: gui(left), top: gui(top) }}
    >
      {content}
    </Slot>
  );
}
